@cmd('pages.clean')
def pages_clean(argv: list):
    """Remove truly blank pages from a PDF.

    A page is considered blank ONLY if it has exactly 0 text characters AND
    0 images.  Pages with even a single character or a tiny image are kept.

    Usage:
        pdf.py pages.clean input.pdf -o output.pdf
    """
    if not argv:
        Output.error('MissingArg', 'PDF path required')
    pdf_path = argv.pop(0)
    out_path = _pop_flag(argv, '-o', '--output')
    if out_path is None:
        Output.error('MissingArg', '--output is required')
    _pop_flag(argv, '-t', '--threshold')
    src = Output.check_file(pdf_path)
    try:
        import pdfplumber
    except ImportError:
        Output.error('DependencyMissing', 'pdfplumber required: Dependency must be preinstalled; report it if missing.')
    blank_indices = []
    total_pages = 0
    try:
        pdf = pdfplumber.open(str(src))
        total_pages = len(pdf.pages)
        for i, page in enumerate(pdf.pages):
            text = (page.extract_text() or '').strip()
            images = page.images if hasattr(page, 'images') else []
            if len(text) == 0 and len(images) == 0:
                blank_indices.append(i)
        pdf.close()
    except Exception as exc:
        Output.error('PDFError', f'Cannot analyze PDF: {exc}', code=3)
    if not blank_indices:
        Output.success({'output': str(src), 'total_pages': total_pages, 'blank_pages_removed': 0, 'message': 'No blank pages found'})
        return
    try:
        import pikepdf
    except ImportError:
        Output.error('DependencyMissing', 'pikepdf required: Dependency must be preinstalled; report it if missing.')
    try:
        doc = pikepdf.open(str(src))
        for idx in sorted(blank_indices, reverse=True):
            if idx < len(doc.pages):
                del doc.pages[idx]
        doc.save(out_path)
        doc.close()
    except Exception as exc:
        Output.error('PDFError', f'Cannot remove blank pages: {exc}', code=4)
    remaining = total_pages - len(blank_indices)
    Output.success({'output': out_path, 'total_pages': total_pages, 'blank_pages_removed': len(blank_indices), 'blank_page_numbers': [i + 1 for i in blank_indices], 'remaining_pages': remaining})
_XMP_MAPPING = {'Title': 'dc:title', 'Author': 'dc:creator', 'Subject': 'dc:description', 'Keywords': 'pdf:Keywords', 'Creator': 'xmp:CreatorTool', 'Producer': 'pdf:Producer'}
_ACCEPTED_KEYS = set(_XMP_MAPPING.keys())
@cmd('meta.get')
