_BIDI_CONTROLS: set[int] = {8206, 8207, 8234, 8235, 8236, 8237, 8238, 8294, 8295, 8296, 8297}
_VARIATION_SELECTORS: set[int] = set(range(65024, 65040))
_NONCHARACTERS: set[int] = set(range(64976, 65008))
