_RE_UNICODE_ESC = re.compile('(\\\\u[0-9a-fA-F]{4})|(\\\\U[0-9a-fA-F]{8})|(\\\\x[0-9a-fA-F]{2})')
def _restore_escapes(s: str) -> str:
    s = html.unescape(s)
    def _dec(m: re.Match) -> str:
        esc = m.group(0)
        try:
            if esc.startswith('\\u') or esc.startswith('\\U'): return chr(int(esc[2:], 16))
            if esc.startswith('\\x'): return chr(int(esc[2:], 16))
        except Exception:
            return esc
        return esc
    return _RE_UNICODE_ESC.sub(_dec, s)
_SUPERSCRIPT_MAP: dict[str, str] = {'⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4', '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9', '⁺': '+', '⁻': '-', '⁼': '=', '⁽': '(', '⁾': ')', 'ⁿ': 'n', 'ᶦ': 'i'}
_SUBSCRIPT_MAP: dict[str, str] = {'₀': '0', '₁': '1', '₂': '2', '₃': '3', '₄': '4', '₅': '5', '₆': '6', '₇': '7', '₈': '8', '₉': '9', '₊': '+', '₋': '-', '₌': '=', '₍': '(', '₎': ')', 'ₐ': 'a', 'ₑ': 'e', 'ₕ': 'h', 'ᵢ': 'i', 'ⱼ': 'j', 'ₖ': 'k', 'ₗ': 'l', 'ₘ': 'm', 'ₙ': 'n', 'ₒ': 'o', 'ₚ': 'p', 'ᵣ': 'r', 'ₛ': 's', 'ₜ': 't', 'ᵤ': 'u', 'ᵥ': 'v', 'ₓ': 'x'}
def _replace_super_sub(s: str) -> str:
    out = []
    for ch in s:
        if ch in _SUPERSCRIPT_MAP:
            out.append(f'<super>{_SUPERSCRIPT_MAP[ch]}</super>')
        elif ch in _SUBSCRIPT_MAP:
            out.append(f'<sub>{_SUBSCRIPT_MAP[ch]}</sub>')
        else:
            out.append(ch)
    return ''.join(out)
_SYMBOL_FALLBACK: dict[str, str] = {}
def _fallback_symbols(s: str) -> str:
    placeholders: dict[str, str] = {}
    def _protect_tag(m: re.Match) -> str:
        key = f'@@TAG{len(placeholders)}@@'
        placeholders[key] = m.group(0)
        return key
    protected = re.sub('</?super>|</?sub>', _protect_tag, s)
    protected = ''.join((_SYMBOL_FALLBACK.get(ch, ch) for ch in protected))
    for k, v in placeholders.items():
